"use client";

import React, { useState, useRef } from "react";
import { motion } from "framer-motion";
import axios from "axios";

const VideoEmotionAnalysis = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [videoFile, setVideoFile] = useState(null);
  const [videoPreview, setVideoPreview] = useState(null);
  const [analysisResults, setAnalysisResults] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Reset states
    setError(null);
    setAnalysisResults(null);

    // Check file type
    if (!file.type.startsWith("video/")) {
      setError("Please upload a valid video file");
      return;
    }

    // Check file size (limit to 100MB)
    if (file.size > 100 * 1024 * 1024) {
      setError("Video file is too large. Please upload a file smaller than 100MB");
      return;
    }

    setVideoFile(file);

    // Create a preview URL
    const previewUrl = URL.createObjectURL(file);
    setVideoPreview(previewUrl);
  };

  const handleAnalyzeVideo = async () => {
    if (!videoFile) {
      setError("Please upload a video file first");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append("video", videoFile);

      const response = await axios.post("http://localhost:5001/analyze-video", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
        timeout: 300000, // 5 minutes timeout for large videos
      });

      setAnalysisResults(response.data);
    } catch (err) {
      console.error("Error analyzing video:", err);
      setError(
        err.response?.data?.error || 
        "Failed to analyze video. Please try again or use a different video file."
      );
    } finally {
      setIsLoading(false);
    }
  };

  const resetAnalysis = () => {
    setVideoFile(null);
    setVideoPreview(null);
    setAnalysisResults(null);
    setError(null);
    
    // Reset file input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  return (
    <div className="space-y-6">
      {/* Video Upload Section */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="bg-[#1A1B20] rounded-lg shadow-md border border-[#2C2D32]/80 p-6"
      >
        <h2 className="text-xl font-semibold text-gray-200 mb-4">Emotion Analysis</h2>
        
        {/* Video Preview */}
        <div className="mb-6 bg-[#101114] rounded-lg aspect-video flex items-center justify-center overflow-hidden">
          {videoPreview ? (
            <video 
              src={videoPreview} 
              controls 
              className="w-full h-full object-contain"
            />
          ) : (
            <div className="text-gray-400 flex flex-col items-center">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              <p>No video uploaded yet</p>
            </div>
          )}
        </div>
        
        {/* Error Message */}
        {error && (
          <div className="mb-4 p-3 bg-red-900/20 border border-red-500/30 rounded-md text-red-300">
            <p>{error}</p>
          </div>
        )}
        
        {/* Upload Controls */}
        <div className="flex flex-col sm:flex-row gap-4 justify-center items-center">
          <label className="px-4 py-2 bg-purple-600 text-white rounded-lg shadow-sm hover:bg-purple-700 transition-colors cursor-pointer">
            {videoFile ? "Change Video" : "Upload Video"}
            <input 
              type="file" 
              accept="video/*" 
              onChange={handleFileChange} 
              className="hidden" 
              ref={fileInputRef}
            />
          </label>
          
          {videoFile && !isLoading && !analysisResults && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={handleAnalyzeVideo}
              className="px-6 py-2 bg-gradient-to-r from-purple-600 to-purple-700 text-white rounded-lg shadow-md hover:shadow-lg transition-all"
            >
              Analyze Emotions
            </motion.button>
          )}
          
          {(isLoading || analysisResults) && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={resetAnalysis}
              className="px-6 py-2 bg-gray-700 text-white rounded-lg shadow-md hover:bg-gray-800 transition-all"
            >
              Reset
            </motion.button>
          )}
        </div>
        
        {/* Loading Indicator */}
        {isLoading && (
          <div className="mt-6 flex flex-col items-center">
            <div className="w-12 h-12 border-4 border-purple-600 border-t-transparent rounded-full animate-spin"></div>
            <p className="mt-4 text-gray-300">Analyzing video emotions... This may take a few minutes.</p>
          </div>
        )}
      </motion.div>
      
      {/* Analysis Results */}
      {analysisResults && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="bg-[#1A1B20] rounded-lg shadow-md border border-[#2C2D32]/80 p-6"
        >
          <h2 className="text-xl font-semibold text-gray-200 mb-6">Emotion Analysis Results</h2>
          
          {/* Dominant Emotion */}
          <div className="mb-6 p-4 bg-purple-900/20 rounded-lg border border-purple-500/30">
            <h3 className="text-lg font-medium text-gray-200 mb-2">Dominant Emotion</h3>
            <div className="flex items-center">
              <div className="h-16 w-16 rounded-full bg-purple-900/30 flex items-center justify-center mr-4">
                <span className="text-2xl font-bold text-purple-300">{analysisResults.dominant_emotion}</span>
              </div>
              <div>
                <p className="text-gray-300">
                  The dominant emotion detected in your video is <span className="font-semibold text-purple-300">{analysisResults.dominant_emotion}</span>.
                </p>
                <p className="text-gray-400 text-sm mt-1">
                  This emotion was detected in {analysisResults.dominant_emotion_count} frames out of {analysisResults.processed_frames} analyzed frames.
                </p>
              </div>
            </div>
          </div>
          
          {/* Emotion Distribution Chart */}
          <div className="mb-6">
            <h3 className="text-lg font-medium text-gray-200 mb-4">Emotion Distribution</h3>
            {analysisResults.chart_base64 && (
              <div className="flex justify-center">
                <img 
                  src={`data:image/png;base64,${analysisResults.chart_base64}`} 
                  alt="Emotion Distribution Chart" 
                  className="max-w-full rounded-lg border border-gray-700"
                />
              </div>
            )}
          </div>
          
          {/* Emotion Percentages */}
          <div className="mb-6">
            <h3 className="text-lg font-medium text-gray-200 mb-4">Emotion Breakdown</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {Object.entries(analysisResults.emotion_percentages || {}).map(([emotion, percentage]) => (
                <div key={emotion} className="flex items-center">
                  <span className="w-24 text-gray-200 capitalize">{emotion}:</span>
                  <div className="w-full bg-gray-700 rounded-full h-2.5 mx-2">
                    <div 
                      className="bg-purple-600 h-2.5 rounded-full" 
                      style={{ width: `${Math.min(100, percentage)}%` }}
                    ></div>
                  </div>
                  <span className="text-gray-200 text-sm">{percentage.toFixed(1)}%</span>
                </div>
              ))}
            </div>
          </div>
          
          {/* Processed Video */}
          {analysisResults.output_video_path && (
            <div>
              <h3 className="text-lg font-medium text-gray-200 mb-4">Processed Video</h3>
              <div className="bg-[#101114] rounded-lg aspect-video flex items-center justify-center overflow-hidden">
                <video 
                  src={`http://localhost:5001/get-video/${analysisResults.output_video_path}`} 
                  controls 
                  className="w-full h-full object-contain"
                />
              </div>
              <div className="mt-4 flex justify-center">
                <a 
                  href={`http://localhost:5001/get-video/${analysisResults.output_video_path}`} 
                  download
                  className="px-4 py-2 bg-purple-600 text-white rounded-lg shadow-sm hover:bg-purple-700 transition-colors"
                >
                  Download Processed Video
                </a>
              </div>
            </div>
          )}
        </motion.div>
      )}
    </div>
  );
};

export default VideoEmotionAnalysis;
